INSERT INTO `rule_config` VALUES ('HIGH_FREQUENCY',35,5.00,'5 or more transactions by the same account within 10 minutes',1),('LOCATION_CHANGE',35,0.01,'Region used in under 1% of account history, between 00:00 and 04:59',1),('UNUSUAL_AMOUNT',40,4.00,'Amount is 4 or more standard deviations above the account average',1);
